/** One circular flag disc. */
export function Flag({ code, className }) {
  const flag = FLAGS[code];
  if (!flag) return null;
  return (
    <svg
      viewBox={flag.viewBox}
      className={className}
      preserveAspectRatio="xMidYMid slice"
      aria-hidden="true"
      dangerouslySetInnerHTML={{ __html: flag.inner }}
    />
  );
}

export function hasFlag(code) {
  return Boolean(FLAGS[code]);
}
